import { useState, useCallback } from "react";
import { Button } from "@/shared/ui/controls/Button";
import { Card } from "@/shared/ui/data/Card";
import { Stack } from "@/shared/ui/layout/Stack";
import { Row as LayoutRow } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

// Vendored from `@/features/settings/pages/SettingsControls` (unresolvable in this sandbox as a
// standalone import — that file's own promoted component only covers its ToggleRow export) — unchanged.
function SettingsRow({ label, hint, children }) {
  return (
    <LayoutRow gap={12} style={{ padding: "10px 0", borderBottom: "1px solid var(--border-soft)" }}>
      <Box style={{ flex: 1, minWidth: 0 }}>
        <Text as="div" size={13} style={{ fontFamily: "var(--sans)", color: "var(--fg)" }}>{label}</Text>
        {hint && <Text as="div" size={11} tone="dim" style={{ fontFamily: "var(--sans)", marginTop: 2 }}>{hint}</Text>}
      </Box>
      {children}
    </LayoutRow>
  );
}
function SettingsSelect({ value, options, onChange }) {
  return (
    // eslint-disable-next-line no-restricted-syntax -- vendored verbatim from the real SettingsControls helper
    <select
      value={value}
      onChange={(e) => { const raw = e.target.value; onChange(typeof value === "number" ? Number(raw) : raw); }}
      className="mono"
      style={{ fontSize: 11.5, background: "var(--bg-elev)", color: "var(--fg)", border: "1px solid var(--border)", borderRadius: 6, padding: "5px 8px", cursor: "pointer" }}
    >
      {options.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
    </select>
  );
}

// Preview-only stand-in for the real `useAppStore().logConfig` — app-internal, unresolvable here.
const DEFAULT_LOG_CONFIG = { maxLines: 10000, maxSizeMb: 20 };

export function LogsRetentionCard({
  onEnforced = () => {},
  flash = () => {},
}: {
  onEnforced?: () => void;
  flash?: (msg: string) => void;
}) {
  const [logConfig, setLogConfig] = useState(DEFAULT_LOG_CONFIG);
  const [busy, setBusy] = useState(false);

  const enforceNow = useCallback(() => {
    setBusy(true);
    flash("Caps enforced.");
    onEnforced();
    setBusy(false);
  }, [flash, onEnforced]);

  const update = (patch) => setLogConfig({ ...logConfig, ...patch });

  return (
    <Card title="Log retention">
      <Stack gap={0}>
        <SettingsRow label="Max lines per log" hint="On enforcement (and at startup), each telemetry log is trimmed to its newest N lines.">
          <SettingsSelect
            value={logConfig.maxLines}
            options={[
              { label: "1,000", value: 1000 },
              { label: "5,000", value: 5000 },
              { label: "10,000 (default)", value: 10000 },
              { label: "50,000", value: 50000 },
              { label: "Unlimited", value: 0 },
            ]}
            onChange={(v) => update({ maxLines: v })}
          />
        </SettingsRow>
        <SettingsRow label="Max size per log" hint="If a log still exceeds this after the line cap, its oldest lines are dropped until it fits. 0 = no limit.">
          <SettingsSelect
            value={logConfig.maxSizeMb}
            options={[
              { label: "5 MB", value: 5 },
              { label: "20 MB (default)", value: 20 },
              { label: "100 MB", value: 100 },
              { label: "No limit", value: 0 },
            ]}
            onChange={(v) => update({ maxSizeMb: v })}
          />
        </SettingsRow>
        <SettingsRow label="Trim logs now" hint="Apply the caps to every telemetry log immediately, instead of waiting for the next startup.">
          <Button size="sm" disabled={busy} onClick={enforceNow}>{busy ? "Enforcing\u2026" : "Enforce now"}</Button>
        </SettingsRow>
      </Stack>
    </Card>
  );
}
